"""生成模板清单 ``image_resources/manifest.json``。

扫描 ``autowsgr/data/images/`` 下的全部 PNG 模板，记录相对路径、像素尺寸、
SHA-256、基准分辨率，并写入由 :mod:`autowsgr.image_resources` 启动校验的
清单文件。

用法（仓库根目录）::

    python python/site-packages/autowsgr/image_resources/generate_manifest.py

说明
----
模板都是裁剪件，图片自身尺寸无法反推采集时的大屏分辨率，因此
``base_resolution`` 取文件名后缀（``_540p`` / ``_720p``）。``data/images/ui/``
下 5 张 600x40 二值标签模板由 ``ui/tabbed_page.py`` 按相对区域裁剪后统一
缩放到 600x40 再比较，与 540p/720p 无关，故记为 ``normalized``；其余无后缀
模板会在生成时直接报错，避免改名后静默回落成 540p。``game_version`` 从
``resources/backend-distribution.json`` 的可选 ``game_version`` 字段读取，
读不到时留空字符串，不在脚本里硬编码版本号。
"""

from __future__ import annotations

import hashlib
import json
import re
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


_THIS_DIR = Path(__file__).resolve().parent
_IMAGE_ROOT = _THIS_DIR.parent / 'data' / 'images'
_MANIFEST_PATH = _THIS_DIR / 'manifest.json'
_INSTALL_ROOT = _THIS_DIR.parents[3]
_BACKEND_DISTRIBUTION = _INSTALL_ROOT / 'resources' / 'backend-distribution.json'

_RESOLUTION_SUFFIX = re.compile(r'_(?P<height>\d{3,4})p(?=_|$)', re.IGNORECASE)
_PNG_SIGNATURE = b'\x89PNG\r\n\x1a\n'

# ui/tabbed_page.py 直接读取这 5 张二值模板，把截图标签栏裁剪后统一缩放到
# 600x40 再比较；600x40 是归一化尺寸，不是 540p/720p 采集尺寸。
_NORMALIZED_UI_TEMPLATES = frozenset(
    {
        'ui/build.png',
        'ui/friend.png',
        'ui/intensify.png',
        'ui/map.png',
        'ui/mission.png',
    }
)


def _read_png_size(path: Path) -> tuple[int, int]:
    """从 PNG 的 IHDR 读取 (width, height)，不依赖 Pillow。"""
    with path.open('rb') as handle:
        header = handle.read(24)
    if len(header) < 24 or header[:8] != _PNG_SIGNATURE:
        raise ValueError(f'不是有效的 PNG 文件: {path}')
    width = int.from_bytes(header[16:20], 'big')
    height = int.from_bytes(header[20:24], 'big')
    return width, height


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open('rb') as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


def _infer_base_resolution(relative_path: str) -> str:
    if relative_path in _NORMALIZED_UI_TEMPLATES:
        return 'normalized'
    match = _RESOLUTION_SUFFIX.search(Path(relative_path).stem)
    if match is not None:
        return f"{match.group('height')}p"
    raise ValueError(
        f'无法判定基准分辨率：{relative_path}（文件名缺少 _540p/_720p 后缀；'
        f'若为 tabbed_page 的 600x40 二值模板，请加入 _NORMALIZED_UI_TEMPLATES）'
    )


def _find_game_version(value: Any) -> str:
    if isinstance(value, dict):
        for key, child in value.items():
            if key == 'game_version' and isinstance(child, str) and child:
                return child
            found = _find_game_version(child)
            if found:
                return found
    elif isinstance(value, list):
        for child in value:
            found = _find_game_version(child)
            if found:
                return found
    return ''


def _read_game_version() -> str:
    try:
        data = json.loads(_BACKEND_DISTRIBUTION.read_text(encoding='utf-8'))
    except (OSError, json.JSONDecodeError):
        return ''
    return _find_game_version(data)


def build_manifest() -> dict[str, Any]:
    entries: list[dict[str, Any]] = []
    for path in sorted(_IMAGE_ROOT.rglob('*')):
        if not path.is_file() or path.suffix.lower() != '.png':
            continue
        relative_path = path.relative_to(_IMAGE_ROOT).as_posix()
        width, height = _read_png_size(path)
        entries.append(
            {
                'path': relative_path,
                'width': width,
                'height': height,
                'sha256': _sha256(path),
                'base_resolution': _infer_base_resolution(relative_path),
            }
        )
    return {
        'schema_version': 1,
        'game_version': _read_game_version(),
        'generated_at': datetime.now(timezone.utc).isoformat(timespec='seconds'),
        'templates': entries,
    }


def main() -> int:
    if not _IMAGE_ROOT.is_dir():
        print(f'模板目录不存在: {_IMAGE_ROOT}', file=sys.stderr)
        return 1
    try:
        manifest = build_manifest()
    except ValueError as exc:
        print(f'生成失败：{exc}', file=sys.stderr)
        return 2
    _MANIFEST_PATH.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2) + '\n',
        encoding='utf-8',
    )
    count = len(manifest['templates'])
    print(f'已生成 {_MANIFEST_PATH}：{count} 项')
    print(f"game_version={manifest['game_version']!r}")
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
